create table if not exists meta_app
(
id                 varchar(64)    not null primary key,
name               varchar(240)   null,
tag                varchar(240)   null,
display_name       varchar(240)   null,
version            varchar(240)   null,
url                text           null,
description        varchar(240)   null,
summary            varchar(1024)  null,
author             varchar(240)   null,
company            varchar(240)   null,
product            varchar(80)    null,
weight             numeric(11, 3) null,
sequence           numeric(22, 3) null,
icon               varchar(240)   null,
latest_version     varchar(240)   null,
application        char           null,
license            varchar(240)   null,
meta_app_store_id  varchar(255)   null,
jar_file_id        varchar(200)   null,
jar_file           varchar(240)   null,
md5                varchar(64)    null,
view_file_id       varchar(200)   null,
view_file          varchar(240)   null,
type               varchar(80)    null,
state              varchar(80)    null,
source             varchar(80)    null,
loader_type        varchar(80)    null,
kind               varchar(80)    null,
is_delete          char           null,
is_primary         char           null,
global             char           null,
reinstall          char           null,
view_file_frontend text           null,
front_tag          varchar(240)   null,
front_version      varchar(240)   null,
front_author       varchar(240)   null,
category_ids       varchar(64)    null,
tenant_id          varchar(64)    null,
create_user        varchar(64)    null,
create_date        timestamp      null,
update_user        varchar(64)    null,
update_date        timestamp      null
);
comment on table meta_app is '已安装应用';
comment on column meta_app.name is '应用';
comment on column meta_app.tag is '标签';
comment on column meta_app.display_name is '显示名称';
comment on column meta_app.version is '版本';
comment on column meta_app.url is '应用资源路径';
comment on column meta_app.description is '说明';
comment on column meta_app.summary is '摘要';
comment on column meta_app.author is '作者';
comment on column meta_app.company is '公司';
comment on column meta_app.product is '产品线';
comment on column meta_app.weight is '权重';
comment on column meta_app.sequence is '排序号';
comment on column meta_app.icon is '图标';
comment on column meta_app.latest_version is '最新版本';
comment on column meta_app.application is '是否应用';
comment on column meta_app.license is '授权';
comment on column meta_app.meta_app_store_id is '应用市场Id';
comment on column meta_app.jar_file_id is '应用jar包';
comment on column meta_app.jar_file is '应用jar包';
comment on column meta_app.md5 is 'md5';
comment on column meta_app.view_file_id is '前端压缩包';
comment on column meta_app.view_file is '前端压缩包';
comment on column meta_app.type is '类型';
comment on column meta_app.state is '安装状态';
comment on column meta_app.source is '来源';
comment on column meta_app.loader_type is '应用加载类型';
comment on column meta_app.kind is '服务状态';
comment on column meta_app.is_delete is '删除';
comment on column meta_app.is_primary is '是否主应用';
comment on column meta_app.global is '全局安装';
comment on column meta_app.reinstall is '可重复安装';
comment on column meta_app.view_file_frontend is '前端压缩包';
comment on column meta_app.front_tag is '前端包tag';
comment on column meta_app.front_version is '前端包版本';
comment on column meta_app.front_author is '前端包作者';
comment on column meta_app.category_ids is '分类';
comment on column meta_app.tenant_id is '租户ID';
comment on column meta_app.create_user is '创建人';
comment on column meta_app.create_date is '创建时间';
comment on column meta_app.update_user is '更新人';
comment on column meta_app.update_date is '更新时间';

