data_id        varchar(240) null,
source         varchar(80)  null,
is_delete      char         null,
tenant_id      varchar(64)  null,
create_user    varchar(64)  null,
create_date    timestamp    null,
update_user    varchar(64)  null,
update_date    timestamp    null
);
create index if not exists idx_name on meta_model_data (name);
comment on table meta_model_data is '模型数据';
comment on column meta_model_data.name is '名称';
